import {solarDetails,dewRisk,auroraAt,validateOrbit,issPasses,bearing} from './field-math.js';
import {weatherAt,savedWeather,coordinateKey} from './mission-weather.js';
import {localParts,localLabel,shortClock} from './observing-time.js';
const NOAA='https://services.swpc.noaa.gov/json/ovation_aurora_latest.json';
const ISS='https://celestrak.org/NORAD/elements/gp.php?CATNR=25544&FORMAT=JSON';
const read=key=>{try{return JSON.parse(localStorage.getItem(key)||'null');}catch{return null;}};
const pending=new Map();
function feed(key,url,ttl){if(pending.has(key))return pending.get(key);const job=loadFeed(key,url,ttl).finally(()=>pending.delete(key));pending.set(key,job);return job;}
async function loadFeed(key,url,ttl){
 const cache=read(key);if(cache?.stamp<=Date.now()&&Date.now()-cache.stamp<ttl)return {...cache,saved:true,offline:navigator.onLine===false};
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);
 try{const response=await fetch(url,{signal:controller.signal});if(!response.ok)throw Error('Data service returned '+response.status);const data=await response.json(),value={stamp:Date.now(),data};try{localStorage.setItem(key,JSON.stringify(value));}catch{}return value;}
 catch(error){if(cache?.data&&cache.stamp<=Date.now())return {...cache,saved:true,offline:true};throw Error(navigator.onLine?'Service unavailable. Retry when connected.':'Offline · download this feed before leaving service.');}finally{clearTimeout(timer);}
}
export function createFieldTools({A,site,getContext,getSnapshot,ensureWeather}){
 const $=id=>document.getElementById(id),view=$('field-view');let active=false,generation=0,lastSolar='',issKey='',lastIss=[],lastRefresh=0;
 view.innerHTML=`<header class="field-heading"><span class="atlas-kicker">A LITTLE MORE NIGHT</span><h2>Beyond the forecast.</h2><p id="field-site"></p><p id="field-time" class="dv-nav-fine"></p><button type="button" id="field-refresh">↻ Refresh open panels</button></header><div class="field-grid">
 <details id="field-solar" class="field-card" open><summary><span class="field-symbol">☾</span><span><strong>Moon &amp; planet clock</strong><small id="solar-summary">Calculated for your selected time</small></span></summary><div class="field-card-body"><div class="lunar-clock"><span class="lunar-orbit" aria-hidden="true">☾</span><div><strong id="lunar-phase"></strong><span id="lunar-light"></span></div></div><dl class="field-facts"><div><dt>Next Moonrise</dt><dd id="lunar-rise"></dd></div><div><dt>Next Moonset</dt><dd id="lunar-set"></dd></div></dl><details id="jupiter-details"><summary>Identify Jupiter’s moons · optional reveal</summary><svg id="jupiter-moons" viewBox="0 0 360 135" role="img" aria-label="Calculated positions of Jupiter’s four largest moons"></svg><p id="jupiter-labels" class="dv-nav-fine"></p><p class="dv-nav-fine">Celestial north up, east left. Diagram only; telescope orientation differs. Moons may hide in Jupiter’s shadow or behind its disk. Not an eyepiece simulation.</p></details><p id="solar-error" role="status"></p></div></details>
 <details id="field-aurora" class="field-card"><summary><span class="field-symbol aurora-symbol">≋</span><span><strong>Aurora watch</strong><small>Near-term activity · local cloud &amp; darkness</small></span></summary><div class="field-card-body"><strong id="aurora-value" class="field-big">Open to check</strong><div class="field-meter"><span id="aurora-bar"></span></div><p id="aurora-status" role="status"></p><p id="aurora-weather"></p><p class="dv-nav-fine">NOAA OVATION: probability overhead near this site, not a promise of seeing aurora. Near-term only; never a five-day aurora forecast.</p><a href="https://www.swpc.noaa.gov/products/aurora-30-minute-forecast" target="_blank" rel="noopener noreferrer">NOAA forecast &amp; explanation ↗</a></div></details>
 <details id="field-air" class="field-card"><summary><span class="field-symbol">◌</span><span><strong>Haze &amp; dew watch</strong><small>Cloud-free does not always mean clear</small></span></summary><div class="field-card-body"><div class="field-facts"><div><span class="atlas-kicker">HAZE INDICATOR</span><strong id="air-value" class="field-big">Open to check</strong></div><div><span class="atlas-kicker">DEW RISK</span><strong id="dew-value" class="field-big">Unknown</strong></div></div><p id="air-status" role="status"></p><p id="dew-status"></p><p class="dv-nav-fine">Air-quality model indicators and a temperature/dew-point estimate. These do not measure seeing, optical clarity or conditions at the telescope.</p><a href="https://open-meteo.com/en/docs/air-quality-api" target="_blank" rel="noopener noreferrer">Open-Meteo / CAMS data ↗</a></div></details>
 <details id="field-iss" class="field-card"><summary><span class="field-symbol">⌁</span><span><strong>ISS fly-bys</strong><small>Look up between telescope targets</small></span></summary><div class="field-card-body"><p id="iss-status" role="status">Open to calculate local passes.</p><ol id="iss-passes"></ol><p class="dv-nav-fine">Predicted sunlit segments above 10° while the Sun is at least 6° below your horizon. Cloud, brightness and local obstructions can prevent visibility. Use your eyes; the app does not track the station with your telescope.</p><a href="https://celestrak.org/NORAD/documentation/gp-data-formats.php" target="_blank" rel="noopener noreferrer">CelesTrak orbit data · Satellite.js ↗</a></div></details></div>`;
 const set=(id,text)=>{if($(id).textContent!==text)$(id).textContent=text;};
 const nowContext=()=>{const c=getContext();return {...c,instant:c.planning?c.instant:new Date()};};
 function weather(){const c=nowContext(),snapshot=getSnapshot()||savedWeather(site),row=weatherAt(snapshot,c.instant),risk=dewRisk(row);set('dew-value',risk.level);set('dew-status',risk.text+(snapshot?' Forecast downloaded '+localLabel(snapshot.stamp,c.zone)+'.':''));const live=weatherAt(snapshot,new Date());set('aurora-weather',`${A&&sunAltitude(new Date())>-6?'It is daylight or bright twilight here.':'Check the northern or southern horizon as appropriate.'} ${live?.cloud_cover!==null&&Number.isFinite(live?.cloud_cover)?Math.round(live.cloud_cover)+'% cloud forecast now.':'No hourly cloud forecast is available here.'}`);}
 function sunAltitude(date){const eq=A.Equator('Sun',date,new A.Observer(site.latitude,site.longitude,site.height||0),true,true);return A.Horizon(date,new A.Observer(site.latitude,site.longitude,site.height||0),eq.ra,eq.dec).altitude;}
 function solar(){const c=nowContext(),key=coordinateKey(site)+':'+Math.floor(c.instant.getTime()/60000);if(key===lastSolar)return;lastSolar=key;
  try{if(!A)throw Error('Astronomy library unavailable.');const d=solarDetails(A,site,c.instant);set('solar-summary',`${d.phaseName} · ${Math.round(d.fraction*100)}% illuminated`);set('lunar-phase',d.phaseName);set('lunar-light',Math.round(d.fraction*100)+'% illuminated');set('lunar-rise',d.rise?localLabel(d.rise,c.zone):'Not within 48 hours');set('lunar-set',d.set?localLabel(d.set,c.zone):'Not within 48 hours');
   const moon=document.querySelector('.lunar-orbit'),waxing=d.phase<180,cos=Math.cos(d.phase*Math.PI/180),left=[],right=[];for(let i=0;i<=40;i++){const y=-28+i*1.4,x=Math.sqrt(Math.max(0,28*28-y*y));left.push([waxing?cos*x:-x,y]);right.push([waxing?x:-cos*x,y]);}const polygon=[...left,...right.reverse()].map(([x,y])=>`${(x+32).toFixed(2)},${(y+32).toFixed(2)}`).join(' ');moon.innerHTML=`<svg viewBox="0 0 64 64"><circle cx="32" cy="32" r="28" class="lunar-dark"/><polygon points="${polygon}" class="lunar-lit"/></svg>`;
   const svg=$('jupiter-moons');svg.replaceChildren();const make=(tag,attrs)=>{const el=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))el.setAttribute(k,v);return el;};svg.append(make('path',{d:'M20 65H340',class:'jovian-axis'}),make('circle',{cx:180,cy:65,r:7,class:'jovian-planet'}));
   const scale=145/Math.max(12,...d.moons.map(m=>Math.abs(m.x)));for(const m of d.moons){const x=180-m.x*scale;svg.append(make('circle',{cx:x,cy:65-m.y*scale,r:3,class:m.behind?'jovian-hidden':'jovian-moon'}));const text=make('text',{x:Math.max(28,Math.min(332,x)),y:95+(d.moons.indexOf(m)%2)*17,'text-anchor':'middle'});text.textContent=m.name;svg.append(text);}svg.dataset.epoch=c.instant.toISOString();set('jupiter-labels','Calculated '+localLabel(c.instant,c.zone)+' · light-travel time included.');set('solar-error','');
  }catch(error){set('solar-error','Solar-system calculations unavailable: '+error.message);$('jupiter-moons').replaceChildren();}
 }
 async function aurora(id){set('aurora-status','Loading NOAA’s current model…');try{const result=await feed('dvsky:aurora:v1',NOAA,5*60000);if(id!==generation)return;const a=auroraAt(result.data,site);set('aurora-value',a.probability+'% overhead');$('aurora-bar').style.width=a.probability+'%';set('aurora-status',`${result.offline?'Saved offline · ':''}Model valid ${localLabel(a.forecast,getContext().zone)} · observations ${shortClock(a.observed,getContext().zone)}. Applies to now, including when planning another date.`);}catch(error){if(id!==generation)return;set('aurora-value','Unavailable');$('aurora-bar').style.width='0';set('aurora-status',error.message);}weather();}
 async function air(id){set('air-status','Loading the atmospheric forecast…');try{const key=coordinateKey(site),url=`https://air-quality-api.open-meteo.com/v1/air-quality?latitude=${site.latitude}&longitude=${site.longitude}&hourly=pm2_5,aerosol_optical_depth,dust&timezone=auto&forecast_days=5&domains=cams_global`,result=await feed('dvsky:air:v1:'+key,url,3600000);if(id!==generation)return;
   if(Date.now()-result.stamp>12*3600000)throw Error('Atmospheric forecast is too old. Reconnect to update.');const data=result.data;if(!Number.isFinite(data.latitude)||!Number.isFinite(data.longitude)||Math.abs(data.latitude-site.latitude)>1||Math.abs(((data.longitude-site.longitude+540)%360)-180)>1)throw Error('Atmospheric forecast location does not match.');const c=nowContext(),p=localParts(c.instant,data.timezone),hour=`${p.date}T${String(p.hour).padStart(2,'0')}:00`,index=data.hourly?.time?.indexOf(hour),aod=data.hourly?.aerosol_optical_depth?.[index],pm=data.hourly?.pm2_5?.[index],dust=data.hourly?.dust?.[index];
   if(!Number.isFinite(aod)||aod<0)throw Error('No atmospheric forecast covers this date and hour.');set('air-value',aod>.3?'Elevated':aod>.15?'Some haze':'Lower haze');set('air-status',`Model aerosol optical depth ${aod.toFixed(2)}${Number.isFinite(pm)?' · PM₂.₅ '+pm.toFixed(0)+' µg/m³':''}${Number.isFinite(dust)?' · dust '+dust.toFixed(0)+' µg/m³':''}. ${result.offline?'Saved offline. ':''}Downloaded ${localLabel(result.stamp,c.zone)}.`);
  }catch(error){if(id!==generation)return;set('air-value','Unknown');set('air-status',error.message);}weather();}
 async function iss(id){set('iss-status','Checking fresh orbit data and local darkness…');try{const result=await feed('dvsky:iss:omm:v1',ISS,2*3600000);if(id!==generation)return;const orbit=validateOrbit(result.data),c=nowContext();if(c.instant.getTime()<orbit.epoch-3*3600000||c.instant.getTime()>=orbit.epoch+72*3600000)throw Error('The selected date is outside this orbit’s valid window. Choose Now or download fresh orbit data.');const coverage=Math.min(36,(orbit.epoch+72*3600000-c.instant.getTime())/3600000).toFixed(1),key=coordinateKey(site)+':'+orbit.epoch+':'+Math.floor(c.instant.getTime()/600000);if(key!==issKey){lastIss=issPasses(A,result.data,site,c.instant);issKey=key;}if(id!==generation)return;
   $('iss-passes').replaceChildren(...lastIss.map(p=>{const el=document.createElement('li'),title=document.createElement('strong'),text=document.createElement('p');el.dataset.start=String(p.start.getTime());el.dataset.end=String(p.end.getTime());title.textContent=localLabel(p.start,c.zone)+' – '+shortClock(p.end,c.zone);text.textContent=`${bearing(p.from)} → ${bearing(p.to)} · up to ${Math.round(p.max)}° high · visible segment about ${Math.round((p.end-p.start)/1000)} seconds`;const clock=document.createElement('span');clock.className='iss-countdown';const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 240 160');svg.setAttribute('role','img');svg.setAttribute('aria-label','Predicted visible ISS path, north at top');const make=(tag,attrs,value)=>{const e=document.createElementNS(svg.namespaceURI,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);if(value)e.textContent=value;return e;};svg.append(make('circle',{cx:120,cy:78,r:60,class:'iss-horizon'}));for(const [label,x,y]of [['N',120,12],['E',190,82],['S',120,152],['W',50,82]])svg.append(make('text',{x,y,'text-anchor':'middle'},label));const points=p.track.map(q=>{const radius=60*(1-q.alt/90),a=q.az*Math.PI/180;return (120+radius*Math.sin(a)).toFixed(2)+','+(78-radius*Math.cos(a)).toFixed(2);}).join(' ');svg.append(make('polyline',{points,class:'iss-track'}));el.append(title,clock,svg,text);return el;}));set('iss-status',`${lastIss.length?`Predicted visible segments over the next ${coverage} hours.`:`No qualifying sunlit pass found in the next ${coverage} hours.`} Orbit epoch ${localLabel(orbit.epoch,c.zone)}${result.offline?' · saved offline':''}. Predictions are suppressed when orbit data is older than 72 hours.`);
  countdowns();}catch(error){if(id!==generation)return;$('iss-passes').replaceChildren();set('iss-status',error.message);}}
 function countdowns(){const c=nowContext();for(const el of $('iss-passes').children){const start=Number(el.dataset.start),end=Number(el.dataset.end),minutes=Math.max(0,Math.ceil((start-Date.now())/60000));el.querySelector('.iss-countdown').textContent=c.planning?'Planned pass':Date.now()>end?'Pass ended':Date.now()>=start?'Predicted visible segment underway':minutes>=60?`Starts in ${Math.floor(minutes/60)}h ${minutes%60}m`:`Starts in about ${minutes} min`;}}
 function refresh(){if(!active)return;set('field-site',site.label);const c=nowContext();set('field-time',(c.planning?'Planned sky · ':'Now · ')+localLabel(c.instant,c.zone));solar();weather();const id=++generation;for(const [name,run] of [['aurora',aurora],['air',air],['iss',iss]])if($('field-'+name).open)run(id);lastRefresh=Date.now();}
 for(const name of ['aurora','air','iss'])$('field-'+name).addEventListener('toggle',()=>{if($('field-'+name).open&&active){ensureWeather();refresh();}});
 $('field-refresh').addEventListener('click',()=>{ensureWeather();refresh();});
 setInterval(()=>{if(active&&!document.hidden){solar();weather();countdowns();if(Date.now()-lastRefresh>5*60000)refresh();}},30000);
 return {activate(){active=true;ensureWeather();refresh();},deactivate(){active=false;generation++;},refresh,locationChanged(){generation++;lastSolar='';issKey='';lastIss=[];for(const id of ['air-value','aurora-value'])set(id,'Checking this location…');$('iss-passes').replaceChildren();if(active)refresh();}};
}
